            justify-content: center;
            position: relative;
            overflow: hidden;
        }

        .result-image img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            transition: transform 0.5s cubic-bezier(0.2, 0.8, 0.2, 1);
        }

        .result-card:hover .result-image img {
            transform: scale(1.08);
        }

        .result-content {
            padding: 28px;
