            transition: color 0.3s ease;
        }

        .result-card:hover .result-description {
            color: var(--white-soft);
        }

        /* Enhanced Pagination */
        .pagination {
            display: flex;
            justify-content: center;
            align-items: center;
            gap: 16px;
            margin-top: 80px;
        }

        .page-btn {
            width: 44px;
            height: 44px;
            border: none;
            background: var(--glass);
            border-radius: 14px;
            color: var(--white-muted);
