    <script>
        // Enhanced, elegant JavaScript for premium interactions
        class AuraSearchHU {
            constructor() {
                this.searchInput = document.getElementById('searchInput');
                this.searchBtn = document.getElementById('searchBtn');
                this.suggestions = document.getElementById('suggestions');
                this.resultsSection = document.getElementById('resultsSection');
                this.resultsGrid = document.getElementById('resultsGrid');
                this.searchTimeout = null;
                this.isTabbing = false;

                this.init();
            }

            init() {
                this.bindEvents();
                this.generateSampleResults();
                this.setupAccessibility();
                this.initializeAnimations();
            }

            bindEvents() {
                // Search input events with enhanced UX
                this.searchInput.addEventListener('input', this.handleInput.bind(this));
                this.searchInput.addEventListener('focus', this.showSuggestions.bind(this));
                this.searchInput.addEventListener('blur', this.hideSuggestionsDelayed.bind(this));
                this.searchInput.addEventListener('keydown', this.handleKeyDown.bind(this));

                // Enhanced search button with micro-interactions
                this.searchBtn.addEventListener('click', this.handleSearch.bind(this));
                this.searchBtn.addEventListener('mousedown', this.addRippleEffect.bind(this));

                // Suggestions with improved interaction
                this.suggestions.addEventListener('mousedown', this.handleSuggestionClick.bind(this));

                // View toggle with smooth transitions
                document.querySelectorAll('.toggle-btn').forEach(btn => {
                    btn.addEventListener('click', this.handleViewToggle.bind(this));
                });

                // Enhanced outside click handling
                document.addEventListener('click', this.handleOutsideClick.bind(this));

                // Smooth scroll handling
                window.addEventListener('scroll', this.handleScroll.bind(this));

                // Tab navigation tracking for accessibility
                document.addEventListener('keydown', this.handleTabNavigation.bind(this));
            }

            handleInput(e) {
                const query = e.target.value.trim();

                if (query.length > 2) {
                    clearTimeout(this.searchTimeout);
                    this.searchTimeout = setTimeout(() => {
                        this.updateSuggestions(query);
                        this.showSuggestions();
                    }, 250); // Slightly faster response
                } else {
                    this.hideSuggestions();
                }
            }

            handleKeyDown(e) {
                if (e.key === 'Enter') {
                    e.preventDefault();
                    this.handleSearch();
                } else if (e.key === 'Escape') {
                    this.hideSuggestions();
                    this.searchInput.blur();
                }
            }

            showSuggestions() {
                this.suggestions.classList.add('show');
            }

            hideSuggestions() {
                this.suggestions.classList.remove('show');
            }

            hideSuggestionsDelayed() {
                setTimeout(() => this.hideSuggestions(), 200);
            }

            updateSuggestions(query) {
                const suggestionData = [
                    { icon: 'search', text: `${query} útmutatók` },
                    { icon: 'star', text: `legjobb ${query}` },
                    { icon: 'trending_up', text: `${query} trendek 2025` },
                    { icon: 'lightbulb', text: `${query} tippek` }
                ];

                this.suggestions.innerHTML = suggestionData.map(item => `
                    <div class="suggestion" data-query="${item.text}">
                        <i class="material-icons suggestion-icon">${item.icon}</i>
                        <span>${item.text}</span>
                    </div>
                `).join('');
            }

            handleSuggestionClick(e) {
                const suggestion = e.target.closest('.suggestion');
                if (suggestion) {
                    const query = suggestion.dataset.query;
                    this.searchInput.value = query;
                    this.hideSuggestions();
                    this.handleSearch();
                }
            }

            handleSearch() {
                const query = this.searchInput.value.trim();
                if (query) {
                    this.addSearchAnimation();
                    setTimeout(() => {
                        this.showSearchResults();
                        this.hideSuggestions();

                        // Ultra-smooth scroll to results with easing
                        setTimeout(() => {
                            this.resultsSection.scrollIntoView({ 
                                behavior: 'smooth',
                                block: 'start'
                            });
                        }, 400);
                    }, 300);
                }
            }

            addSearchAnimation() {
                this.searchBtn.style.transform = 'scale(0.9) rotate(15deg)';
                setTimeout(() => {
                    this.searchBtn.style.transform = '';
                }, 150);
            }

            showSearchResults() {
                this.resultsSection.classList.remove('hidden');
                this.renderResults();
            }

            handleViewToggle(e) {
                const btn = e.target.closest('.toggle-btn');
                const view = btn.dataset.view;

                // Update active state with smooth animation
                document.querySelectorAll('.toggle-btn').forEach(b => {
                    b.classList.remove('active');
                    b.style.transform = 'scale(1)';
                });
                btn.classList.add('active');
                btn.style.transform = 'scale(1.05)';
                setTimeout(() => btn.style.transform = 'scale(1)', 200);

                // Update grid layout with smooth transition
                this.resultsGrid.style.transition = 'all 0.5s cubic-bezier(0.2, 0.8, 0.2, 1)';
                if (view === 'list') {
                    this.resultsGrid.style.gridTemplateColumns = '1fr';
                } else {
                    this.resultsGrid.style.gridTemplateColumns = 'repeat(auto-fit, minmax(340px, 1fr))';
                }
            }

            handleOutsideClick(e) {
                if (!e.target.closest('.search-container')) {
                    this.hideSuggestions();
                }
            }

            handleScroll() {
                const header = document.querySelector('.header');
                const scrollY = window.scrollY;

                if (scrollY > 100) {
                    header.style.background = 'rgba(0, 0, 0, 0.95)';
                    header.style.borderBottomColor = 'rgba(255, 255, 255, 0.15)';
                } else {
                    header.style.background = 'rgba(0, 0, 0, 0.85)';
                    header.style.borderBottomColor = 'rgba(255, 255, 255, 0.08)';
                }
            }

            addRippleEffect(e) {
                const btn = e.currentTarget;
                const rect = btn.getBoundingClientRect();
                const x = e.clientX - rect.left;
                const y = e.clientY - rect.top;

                const ripple = document.createElement('span');
                ripple.style.cssText = `
                    position: absolute;
                    width: 20px;
                    height: 20px;
                    background: rgba(255, 255, 255, 0.3);
                    border-radius: 50%;
                    transform: scale(0);
                    left: ${x - 10}px;
                    top: ${y - 10}px;
                    pointer-events: none;
                    animation: ripple 0.6s ease-out;
                `;

                btn.appendChild(ripple);
                setTimeout(() => ripple.remove(), 600);
            }

            setupAccessibility() {
                // Enhanced keyboard navigation
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'Tab') {
                        document.body.classList.add('user-is-tabbing');
                        this.isTabbing = true;
                    }
                });

                document.addEventListener('mousedown', () => {
                    document.body.classList.remove('user-is-tabbing');
                    this.isTabbing = false;
                });
            }

            handleTabNavigation(e) {
                if (e.key === 'Tab') {
                    this.isTabbing = true;
                    setTimeout(() => this.isTabbing = false, 150);
                }
            }

            initializeAnimations() {
                // Add CSS for ripple animation
                const style = document.createElement('style');
                style.textContent = `
                    @keyframes ripple {
                        to {
                            transform: scale(4);
                            opacity: 0;
                        }
                    }
                `;
                document.head.appendChild(style);
            }

